{
  "avaliacoes": [
    {
      "id": "Ef3c7cfa7f3c06b00",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "Para FPSOs/FSUs, o sistema de integridade deve ajustar escopo, metodologia e frequência de inspeção à idade e à condição do vaso; em vida tardia, a execução do programa pode demandar recursos adicionais para cumprir o plano.",
          "trechos": [
            "Ef3c7cfa7f3c06b00:0:695"
          ],
          "condicoes": [
            "no contexto de ameaças de envelhecimento e late life",
            "quando a instalação precisa manter os programas de inspeção conforme planejado"
          ],
          "limites": [
            "a fonte expressa expectativa regulatória e boa prática em contexto do Reino Unido",
            "não define quantitativamente quais recursos adicionais são necessários nem quando devem ser mobilizados"
          ]
        },
        {
          "proposicao": "A revisão holística de anomalias em aberto, em intervalos adequados, é indicada para identificar questões subjacentes, ameaças globais de integridade e potencial de colapso progressivo.",
          "trechos": [
            "Ef3c7cfa7f3c06b00:695:1346"
          ],
          "condicoes": [
            "quando existem anomalias estruturais abertas a acompanhar",
            "no contexto de integridade estrutural de FPSOs/FSUs"
          ],
          "limites": [
            "o trecho não define periodicidade única nem método detalhado de priorização",
            "a relação está formulada como diretriz, não como resultado experimental"
          ]
        },
        {
          "proposicao": "A alta gestão deve manter visibilidade dos backlogs de inspeção e reparo de itens SECE e não SECE, e esses backlogs devem permanecer dentro de limites aceitáveis.",
          "trechos": [
            "Ef3c7cfa7f3c06b00:1346:2040"
          ],
          "condicoes": [
            "no contexto de gestão de backlog de inspeção e reparo",
            "abrangendo itens críticos de segurança e itens não classificados como SECE"
          ],
          "limites": [
            "a fonte não informa como calcular ou definir os limites aceitáveis",
            "o trecho não apresenta método de priorização entre tipos de backlog"
          ]
        }
      ]
    },
    {
      "id": "Ea87edefb4cabce1b",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "O sistema de integridade deve incluir inspeção e manutenção de sistemas marítimos, como ballast, bilge e seawater, para evitar comunicação com o mar ou entre tanques e preservar funcionalidade e disponibilidade em emergências.",
          "trechos": [
            "Ea87edefb4cabce1b:700:1393"
          ],
          "condicoes": [
            "no contexto de estabilidade e estanqueidade do casco",
            "quando os sistemas marítimos participam da contenção e da resposta a emergências"
          ],
          "limites": [
            "a fonte não detalha periodicidades nem critérios de aceitação",
            "o enquadramento é de orientação regulatória do Reino Unido"
          ]
        },
        {
          "proposicao": "Portas e aberturas estanques, além de sistemas usados para gerir estabilidade e esforços no casco, devem estar submetidos a regimes adequados de manutenção, inspeção e teste.",
          "trechos": [
            "Ea87edefb4cabce1b:700:1393"
          ],
          "condicoes": [
            "quando esses sistemas são necessários em diferentes fases operacionais",
            "incluindo instrumentos e sistemas remotos associados ao controle de carga e lastro"
          ],
          "limites": [
            "o trecho não apresenta regime padrão nem frequência fixa",
            "não há detalhamento de compatibilidade com estratégias de manutenção baseadas em risco"
          ]
        },
        {
          "proposicao": "A integridade de tubulações, válvulas e penetrações associadas aos sistemas de carga, blanketing e offloading deve ser mantida para prevenir perda de contenção, com revisões periódicas para detectar mudanças de longo prazo nas características do processo e dos fluidos.",
          "trechos": [
            "Ea87edefb4cabce1b:1393:2092",
            "Ea87edefb4cabce1b:2092:2403"
          ],
          "condicoes": [
            "no contexto de sistemas de carga, inert gas ou hydrocarbon blanketing e offloading",
            "quando alterações graduais de processo ou composição podem afetar a integridade"
          ],
          "limites": [
            "a fonte não especifica como traduzir essas revisões em campanhas, paradas ou sobressalentes",
            "não define critérios quantitativos de perda de contenção"
          ]
        }
      ]
    },
    {
      "id": "E119c3b872a9b25ba",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Backlog de manutenção baixo ou em redução aparece associado à existência de uma função forte de planejamento, com recursos onshore e offshore que extraem, categorizam e priorizam a manutenção e constroem planos em múltiplos horizontes de tempo.",
          "trechos": [
            "E119c3b872a9b25ba:0:696"
          ],
          "condicoes": [
            "quando o planejamento considera trabalho de projeto, programas operacionais, recursos periféricos, leitos e níveis de pessoal",
            "quando a implementação é coordenada pela gestão offshore"
          ],
          "limites": [
            "a fonte descreve característica observada, não prova causal universal",
            "não compara quantitativamente essa organização com arranjos alternativos"
          ]
        },
        {
          "proposicao": "A coordenação do planejamento offshore com operações, projetos e gestão da manutenção ajuda a administrar pontos de estrangulamento e a reduzir o impacto do trabalho corretivo sobre a manutenção planejada.",
          "trechos": [
            "E119c3b872a9b25ba:696:1394"
          ],
          "condicoes": [
            "quando existe papel de planejamento offshore ativo",
            "quando há necessidade de compatibilizar manutenção corretiva com manutenção planejada"
          ],
          "limites": [
            "o trecho não enumera todos os possíveis pinch points",
            "não estabelece critério de priorização entre produção, projeto e manutenção"
          ]
        },
        {
          "proposicao": "Definições simplificadas de backlog tendem a tornar mais simples o agendamento, o planejamento, o ranqueamento por criticidade e a compreensão gerencial das necessidades de recursos.",
          "trechos": [
            "E119c3b872a9b25ba:1394:2093"
          ],
          "condicoes": [
            "quando backlog é tratado como manutenção não concluída dentro de um período fixo após a data prevista",
            "quando esse período considera fatores como criticidade do equipamento e intervalo de manutenção"
          ],
          "limites": [
            "a própria fonte afirma que a indústria usa definições variadas",
            "não há janela temporal única nem fórmula universal apresentada"
          ]
        }
      ]
    },
    {
      "id": "Eb562e32cd22ae2d0",
      "pertinente": true,
      "tipo": "opiniao",
      "achados": [
        {
          "proposicao": "Para equipamentos de baixa criticidade, o trabalho propõe manutenção corretiva planejada como estratégia compatível com a restrição de recursos humanos a bordo, condicionada a boa gestão de sobressalentes para recompor a função após falhas.",
          "trechos": [
            "Eb562e32cd22ae2d0:0:694"
          ],
          "condicoes": [
            "no âmbito da estratégia proposta pelo autor",
            "quando os equipamentos são classificados como de baixa criticidade",
            "em contexto offshore com restrição de mantenedores a bordo"
          ],
          "limites": [
            "trata-se de proposição metodológica autoral, não norma",
            "o trecho não define critérios de criticidade nem níveis de estoque de sobressalentes"
          ]
        },
        {
          "proposicao": "Para equipamentos de maior criticidade, a definição da estratégia de manutenção é vinculada à análise de modos de falha e de dados de confiabilidade para apoiar a escolha da técnica de manutenção e da periodicidade preventiva.",
          "trechos": [
            "Eb562e32cd22ae2d0:0:694"
          ],
          "condicoes": [
            "no âmbito da estratégia proposta pelo autor",
            "quando os equipamentos são de maior criticidade"
          ],
          "limites": [
            "o trecho remete a outro capítulo para detalhes e não traz o procedimento completo aqui",
            "não demonstra validação ampla para FPSOs em geral"
          ]
        },
        {
          "proposicao": "A metodologia proposta foi concebida para implantação da estratégia de manutenção ainda antes do início da operação, em fase de projeto, construção, montagem, comissionamento e start-up, quando fornecedores já estão definidos e o detalhamento do projeto está avançado.",
          "trechos": [
            "Eb562e32cd22ae2d0:694:1393"
          ],
          "condicoes": [
            "no contexto da metodologia da dissertação",
            "para unidades marítimas de produção de petróleo e gás"
          ],
          "limites": [
            "é uma proposta de aplicação em fases específicas do empreendimento, não requisito universal",
            "o trecho não apresenta resultados comparativos com implantação em fases mais tardias"
          ]
        }
      ]
    },
    {
      "id": "E0eb4e0f32e02e456",
      "pertinente": false,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A fonte apresenta definições gerais de manutenção preditiva, preventiva e corretiva e menciona indicadores como confiabilidade e disponibilidade, mas não trata de priorização, backlog, diferimentos, sobressalentes, paradas, campanhas ou medidas compensatórias em FPSOs.",
          "trechos": [
            "E0eb4e0f32e02e456:0:696",
            "E0eb4e0f32e02e456:696:1393",
            "E0eb4e0f32e02e456:1393:2086"
          ],
          "condicoes": [],
          "limites": [
            "o conteúdo é genérico para ativos do setor energético",
            "não oferece recorte específico para o foco desta rodada"
          ]
        }
      ]
    },
    {
      "id": "Eb40d549a548097e1",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "Para unidades envelhecidas, a fonte indica programa de inspeção reforçado baseado no histórico da unidade e de unidades similares, além de planos de inspeção plurianuais com progresso atualizado.",
          "trechos": [
            "Eb40d549a548097e1:696:1388"
          ],
          "condicoes": [
            "quando se trata de unidades ageing",
            "no contexto de sistemas de integridade estrutural e inspeção"
          ],
          "limites": [
            "a fonte não define intensidade mínima do reforço nem frequência padronizada",
            "o histórico de sister units é citado como base possível, sem método detalhado de extrapolação"
          ]
        },
        {
          "proposicao": "Como critério de sucesso do sistema de integridade estrutural, a fonte espera registro de backlog de inspeções acompanhado das respectivas avaliações de risco, além de sistema de gestão de anomalias com critérios e justificativas de prioridade.",
          "trechos": [
            "Eb40d549a548097e1:696:1388",
            "Eb40d549a548097e1:1388:2085"
          ],
          "condicoes": [
            "no contexto de SIM para unidades móveis ou FPSOs",
            "quando há backlog de inspeção e anomalias a gerir"
          ],
          "limites": [
            "o trecho não prescreve escala única de prioridade nem método único de risco",
            "trata-se de expectativa de boa prática/inspeção, não de demonstração experimental"
          ]
        },
        {
          "proposicao": "Quando a instalação passa longos períodos sem docagem, a integridade estrutural requer atenção especial, e uma combinação entre inspeções periódicas tradicionais de classificação e avaliações RBI pode ser usada para demonstrar atendimento às expectativas de abordagem por objetivos.",
          "trechos": [
            "Eb40d549a548097e1:1388:2085",
            "Eb40d549a548097e1:2085:2304"
          ],
          "condicoes": [
            "quando a instalação não estará sujeita a dry docking por períodos prolongados",
            "no contexto de integração entre Class e Risk Based Inspection"
          ],
          "limites": [
            "a própria fonte ressalta que convenções e códigos da IMO não preveem RBI",
            "o trecho não define como equilibrar, na prática, o esquema periódico tradicional e o RBI"
          ]
        }
      ]
    }
  ],
